// SATBot — SPaG Question Sets (multiple years)
// Original questions in the style of KS2 SATs SPaG Paper 1

const SPAG_SETS = [
  {
    year: "2026",
    questions: [
      {id:1,marks:1,topic:"Sentence types",q:"Which sentence must end with a question mark?",type:"mcq",options:["Kai asked whether the shop was open","Is the shop open on Sundays","I wonder if the shop is open","Please check if the shop is open"],answer:"Is the shop open on Sundays",explanation:"Only 'Is the shop open on Sundays' is a direct question — it starts with a verb and asks something. The others report or mention a question, so they are statements or commands."},
      {id:2,marks:1,topic:"Formality",q:"Which sentence is the most formal?",type:"mcq",options:["Grab a seat, everyone!","Take a seat, won't you?","Pop yourselves down.","Please take your seats."],answer:"Please take your seats.",explanation:"'Please take your seats' is polite and uses no slang or contractions. 'Grab', 'pop yourselves down' and 'won't you' are informal."},
      {id:3,marks:1,topic:"Word formation",q:"Which suffix can be added to the verb 'enjoy' to make a noun?",type:"mcq",options:["-ment","-ous","-less","-ly"],answer:"-ment",explanation:"enjoy + ment = enjoyment (a noun). The suffix '-ment' often turns verbs into nouns: develop → development, move → movement."},
      {id:4,marks:1,topic:"Punctuation",q:"Which sentence is punctuated correctly?",type:"mcq",options:["Max – my older – brother is learning to drive.","Max – my older brother – is learning to drive.","Max my older – brother – is learning to drive.","Max my older brother – is learning – to drive."],answer:"Max – my older brother – is learning to drive.",explanation:"The pair of dashes goes around the extra information 'my older brother'. If you remove it, the sentence still makes sense: 'Max is learning to drive.'"},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence uses a colon correctly?",type:"mcq",options:["You will need: three things a torch, a map and a whistle.","You will need three: things a torch, a map and a whistle.","You will need three things: a torch, a map and a whistle.","You will: need three things a torch, a map and a whistle."],answer:"You will need three things: a torch, a map and a whistle.",explanation:"A colon introduces a list after a complete clause. 'You will need three things' is complete, so the colon goes straight after it."},
      {id:6,marks:1,topic:"Standard English",q:"Which sentence is NOT written in Standard English?",type:"mcq",options:["We were late for the match.","We was late for the match.","The coach was not pleased.","Our team still won the game."],answer:"We was late for the match.",explanation:"In Standard English, 'we' takes 'were': 'We were late'. 'We was' is a non-standard (dialect) form."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence is punctuated correctly?",type:"mcq",options:["We watched the fireworks from the hill?","What a brilliant display that was!","How long did the display last.","Where did you stand!"],answer:"What a brilliant display that was!",explanation:"'What a brilliant display that was' is an exclamation, so it ends with an exclamation mark. The questions need question marks and the statement needs a full stop."},
      {id:8,marks:1,topic:"Vocabulary",q:"Which word is a synonym of 'reluctant' in the sentence below?\n\n\"Ben was reluctant to jump into the cold pool.\"",type:"mcq",options:["unwilling","eager","afraid","quick"],answer:"unwilling",explanation:"'Reluctant' means not wanting to do something — 'unwilling'. 'Eager' is its opposite."},
      {id:9,marks:1,topic:"Punctuation",q:"Which sentence uses a comma correctly after a fronted adverbial?",type:"mcq",options:["After the storm, the garden was covered in leaves.","After, the storm the garden was covered in leaves.","After the storm the garden, was covered in leaves.","After the storm the garden was covered, in leaves."],answer:"After the storm, the garden was covered in leaves.",explanation:"'After the storm' is a fronted adverbial (it tells us when). The comma goes straight after it, before the main clause."},
      {id:10,marks:1,topic:"Vocabulary",q:"Which word is a synonym of 'fragile'?",type:"mcq",options:["delicate","sturdy","heavy","ancient"],answer:"delicate",explanation:"'Fragile' means easily broken — 'delicate'. 'Sturdy' is an antonym."},
      {id:11,marks:1,topic:"Formality",q:"Which word completes the sentence in the most formal way?\n\n\"We hope to ______ your approval for the new playground.\"",type:"mcq",options:["obtain","grab","get hold of","pick up"],answer:"obtain",explanation:"'Obtain' is the formal choice. 'Grab', 'get hold of' and 'pick up' are informal."},
      {id:12,marks:1,topic:"Punctuation",q:"Which sentence uses brackets correctly?",type:"mcq",options:["Luna (a grey rabbit from Leeds) escaped from her hutch.","Luna a (grey rabbit from Leeds) escaped from her hutch.","Luna a grey rabbit (from Leeds escaped) from her hutch.","(Luna a grey rabbit) from Leeds escaped from her hutch."],answer:"Luna (a grey rabbit from Leeds) escaped from her hutch.",explanation:"Brackets go around the whole extra piece of information: 'a grey rabbit from Leeds'. Without it the sentence still works: 'Luna escaped from her hutch.'"},
      {id:13,marks:1,topic:"Verb forms",q:"Which verb is in the wrong tense in the sentence below?\n\n\"When you bake a cake, it is important that you weigh the flour carefully and mixed the ingredients well.\"",type:"mcq",options:["bake","is","weigh","mixed"],answer:"mixed",explanation:"The instructions are in the present tense ('bake', 'is', 'weigh'), so 'mixed' should be 'mix'."},
      {id:14,marks:1,topic:"Punctuation",q:"Which sentence uses a pair of commas correctly?",type:"mcq",options:["The concert, although it started late, was a huge success.","The concert although, it started late, was a huge success.","The concert although it started, late was, a huge success.","The, concert although it started late, was a huge success."],answer:"The concert, although it started late, was a huge success.",explanation:"The commas mark off the subordinate clause 'although it started late' that interrupts the main clause."},
      {id:15,marks:1,topic:"Verb forms",q:"How does changing the modal verb change the meaning of the second sentence?\n\n1. We will visit Gran on Sunday.\n2. We might visit Gran on Sunday.",type:"mcq",options:["It makes the visit certain.","It shows the visit is possible but not certain.","It puts the visit in the past.","It turns the sentence into a command."],answer:"It shows the visit is possible but not certain.",explanation:"'Will' shows certainty. 'Might' shows possibility — the visit may or may not happen."},
      {id:16,marks:1,topic:"Clauses",q:"What is the grammatical term for the part in capitals?\n\n\"You can't play outside UNTIL YOU HAVE FINISHED YOUR HOMEWORK.\"",type:"mcq",options:["a preposition phrase","a subordinate clause","a main clause","a noun phrase"],answer:"a subordinate clause",explanation:"It begins with the subordinating conjunction 'until' and contains a verb ('have finished'), but it does not make sense on its own — so it is a subordinate clause."},
      {id:17,marks:1,topic:"Sentence types",q:"The punctuation has been removed from this sentence. What type of sentence is it?\n\n\"How quickly the summer holidays pass\"",type:"mcq",options:["statement","question","command","exclamation"],answer:"exclamation",explanation:"It begins with 'How', has a subject and a verb, and expresses strong feeling — a grammatical exclamation."},
      {id:18,marks:1,topic:"Conjunctions",q:"Which word is the conjunction in the sentence below?\n\n\"Dad washed the car while we tidied the garden.\"",type:"mcq",options:["Dad","washed","while","tidied"],answer:"while",explanation:"'While' joins the two clauses and tells us the two things happened at the same time."},
      {id:19,marks:1,topic:"Verb forms",q:"Which sentence uses the past progressive?",type:"mcq",options:["What did they build?","What are they building?","What were they building?","What might they build?"],answer:"What were they building?",explanation:"The past progressive uses was/were + a verb ending in -ing: 'were building'."},
      {id:20,marks:1,topic:"Word formation",q:"Which prefix makes the antonym of 'patient'?",type:"mcq",options:["im","un","dis","in"],answer:"im",explanation:"im + patient = impatient. The prefix 'im-' is often used before words starting with p or m (impossible, immature)."},
      {id:21,marks:1,topic:"Verb forms",q:"Which option completes the sentence in the past perfect?\n\n\"______ before the film started.\"",type:"mcq",options:["We buy popcorn","We were buying popcorn","We had bought popcorn","We have bought popcorn"],answer:"We had bought popcorn",explanation:"The past perfect uses 'had' + past participle ('had bought'). It shows one past action happened before another."},
      {id:22,marks:1,topic:"Word classes",q:"Which list contains only the verbs in this sentence?\n\n\"Priya packed her bag, locked the door and hurried to the station.\"",type:"mcq",options:["packed, locked, hurried","bag, door, station","her, the, to","packed, door, station"],answer:"packed, locked, hurried",explanation:"'Packed', 'locked' and 'hurried' are the actions Priya did. 'Bag', 'door' and 'station' are nouns."},
      {id:23,marks:1,topic:"Clauses",q:"Write a relative pronoun to complete the sentence below.\n\n\"The author, ______ wrote my favourite book, is visiting our school.\"",type:"short",answer:"who",explanation:"'Who' is the relative pronoun for a person. It introduces the relative clause 'who wrote my favourite book'."},
      {id:24,marks:1,topic:"Punctuation",q:"Which sentence uses inverted commas correctly?",type:"mcq",options:["Maya pointed at the sky. \"Look, a shooting star!\" she gasped.","Maya pointed at the sky. \"Look, a shooting star! she gasped.\"","Maya pointed at the sky \"Look, a shooting star!\" she gasped.","\"Maya pointed at the sky. Look, a shooting star!\" she gasped."],answer:"Maya pointed at the sky. \"Look, a shooting star!\" she gasped.",explanation:"Only the words Maya actually says go inside the inverted commas, and the exclamation mark comes before the closing inverted commas."},
      {id:25,marks:1,topic:"Tense",q:"Which sentence is written in the simple past?",type:"mcq",options:["The children run to the gate and wave at the bus.","The children ran to the gate and waved at the bus.","The children are running to the gate and waving at the bus.","The children have run to the gate and waved at the bus."],answer:"The children ran to the gate and waved at the bus.",explanation:"The simple past uses a single past-tense verb: 'ran' and 'waved'. The others are present, present progressive and present perfect."},
      {id:26,marks:1,topic:"Clauses",q:"Which part of this sentence is the relative clause?\n\n\"The castle, which was built in 1250, stands on a hill.\"",type:"mcq",options:["The castle","which was built in 1250","stands on a hill","on a hill"],answer:"which was built in 1250",explanation:"A relative clause starts with a relative pronoun ('which') and adds information about a noun ('the castle')."},
      {id:27,marks:1,topic:"Punctuation",q:"Which sentence uses a semi-colon correctly?",type:"mcq",options:["The river flooded the fields; the farmers moved their sheep to higher ground.","The river; flooded the fields the farmers moved their sheep to higher ground.","The river flooded; the fields the farmers moved their sheep to higher ground.","The river flooded the fields the farmers; moved their sheep to higher ground."],answer:"The river flooded the fields; the farmers moved their sheep to higher ground.",explanation:"A semi-colon joins two closely related main clauses. Both 'The river flooded the fields' and 'the farmers moved their sheep to higher ground' are complete."},
      {id:28,marks:1,topic:"Punctuation",q:"Write the contracted form of the words 'does not'.",type:"short",answer:"doesn't",explanation:"does + not = doesn't. The apostrophe replaces the missing letter 'o'."},
      {id:29,marks:1,topic:"Word classes",q:"Which word is a preposition in the sentence below?\n\n\"The cat slept beneath the warm radiator all afternoon.\"",type:"mcq",options:["slept","beneath","warm","afternoon"],answer:"beneath",explanation:"'Beneath' shows where the cat was in relation to the radiator — it is a preposition."},
      {id:30,marks:1,topic:"Punctuation",q:"Which sentence uses a dash correctly?",type:"mcq",options:["The sky turned black – a storm was coming.","The sky – turned black a storm was coming.","The – sky turned black a storm was coming.","The sky turned black a storm – was coming."],answer:"The sky turned black – a storm was coming.",explanation:"A single dash can mark the boundary between two main clauses: 'The sky turned black' and 'a storm was coming'."},
      {id:31,marks:1,topic:"Word formation",q:"Complete the sentence with a word from the same word family as 'decide'.\n\n\"Choosing a team captain was a difficult ______.\"",type:"short",answer:"decision",explanation:"'Decision' is the noun from the same word family as the verb 'decide' (decide → decision → decisive)."},
      {id:32,marks:1,topic:"Word classes",q:"In which sentence is 'light' an adjective?",type:"mcq",options:["The bag was light enough to carry.","Please light the candles.","The light was too bright.","We waited for the light to turn green."],answer:"The bag was light enough to carry.",explanation:"Here 'light' describes the bag (not heavy), so it is an adjective. In the others it is a verb or a noun."},
      {id:33,marks:1,topic:"Punctuation",q:"Which sentence uses apostrophes correctly?",type:"mcq",options:["It's the dog that's always barking.","Its the dog that's always barking.","It's the dog thats always barking.","Its' the dog that's always barking."],answer:"It's the dog that's always barking.",explanation:"'It's' = it is and 'that's' = that is. Both need an apostrophe to show missing letters."},
      {id:34,marks:1,topic:"Conjunctions",q:"Which word is the subordinating conjunction in the sentence below?\n\n\"We stayed indoors because it was raining heavily.\"",type:"mcq",options:["stayed","because","it","heavily"],answer:"because",explanation:"'Because' introduces the subordinate clause 'because it was raining heavily', which gives the reason."},
      {id:35,marks:1,topic:"Punctuation",q:"Which sentence uses a hyphen correctly?",type:"mcq",options:["We bought a second-hand bike at the market.","We bought a second hand-bike at the market.","We-bought a second hand bike at the market.","We bought a second hand bike at-the market."],answer:"We bought a second-hand bike at the market.",explanation:"'Second-hand' is a compound adjective describing the bike, so the two words are joined with a hyphen."},
      {id:36,marks:1,topic:"Sentence types",q:"Sam wants to know what time the concert starts. Which question is written and punctuated correctly?",type:"mcq",options:["What time does the concert start?","what time does the concert start?","What time does the concert start.","What time, does the concert start?"],answer:"What time does the concert start?",explanation:"A question needs a capital letter at the start and a question mark at the end, with no unnecessary commas."},
      {id:37,marks:1,topic:"Sentence structure",q:"What is the object of the sentence below?\n\n\"The goalkeeper caught the ball.\"",type:"mcq",options:["The goalkeeper","caught","the ball","the"],answer:"the ball",explanation:"The subject does the action (the goalkeeper). The object has the action done to it: 'the ball'."},
      {id:38,marks:1,topic:"Punctuation",q:"How do the commas change the meaning of the second sentence?\n\n1. My brother who lives in Leeds is a nurse.\n2. My brother, who lives in Leeds, is a nurse.",type:"mcq",options:["In sentence 2, I have only one brother.","In sentence 2, I have more than one brother.","In sentence 2, my brother no longer lives in Leeds.","The commas do not change the meaning."],answer:"In sentence 2, I have only one brother.",explanation:"Without commas, 'who lives in Leeds' tells you which brother (so there are others). With commas, it is just extra information about my only brother."},
      {id:39,marks:1,topic:"Word classes",q:"Which list contains only the nouns in this sentence?\n\n\"The excited children waited at the gate for their teacher.\"",type:"mcq",options:["children, gate, teacher","excited, waited, their","children, waited, gate","the, at, for"],answer:"children, gate, teacher",explanation:"'Children', 'gate' and 'teacher' name people and things — they are nouns."},
      {id:40,marks:1,topic:"Punctuation",q:"Which passage uses capital letters and full stops correctly?",type:"mcq",options:["Owls hunt at night. They have excellent hearing.","owls hunt at night. they have excellent hearing.","Owls hunt at night they have excellent hearing.","Owls hunt. at night They have excellent hearing."],answer:"Owls hunt at night. They have excellent hearing.",explanation:"There are two sentences, so each starts with a capital letter and ends with a full stop."},
      {id:41,marks:1,topic:"Verb forms",q:"Rewrite the sentence below in the active. Remember to punctuate your answer correctly.\n\n\"The window was broken by the ball.\"",type:"short",answer:"The ball broke the window.",explanation:"In the active, the thing doing the action ('the ball') becomes the subject: 'The ball broke the window.'"},
      {id:42,marks:1,topic:"Word classes",q:"Which word is a possessive pronoun in the sentence below?\n\n\"That umbrella is mine, but the red one belongs to Zara.\"",type:"mcq",options:["That","umbrella","mine","red"],answer:"mine",explanation:"'Mine' is a possessive pronoun — it shows ownership and replaces a noun phrase ('my umbrella')."},
      {id:43,marks:1,topic:"Sentence structure",q:"Which is the longest noun phrase in the sentence below?\n\n\"The tiny striped kitten played happily in the garden.\"",type:"mcq",options:["The tiny striped kitten","the garden","played happily","kitten"],answer:"The tiny striped kitten",explanation:"A noun phrase is a noun plus the words that describe it. 'The tiny striped kitten' is the longest."},
      {id:44,marks:1,topic:"Verb forms",q:"Which sentence uses the subjunctive?",type:"mcq",options:["If I were you, I would apologise.","If I was late, I would run.","If you are hungry, have a snack.","If it rains, we will stay inside."],answer:"If I were you, I would apologise.",explanation:"'If I were…' is the subjunctive form, used for imaginary or hypothetical situations."},
      {id:45,marks:1,topic:"Verb forms",q:"Rewrite the sentence below in the passive. Remember to punctuate your answer correctly.\n\n\"Omar painted the fence.\"",type:"short",answer:"The fence was painted by Omar.",accept:["The fence was painted."],explanation:"In the passive, the object ('the fence') becomes the subject, followed by 'was' + past participle: 'The fence was painted by Omar.'"},
      {id:46,marks:1,topic:"Sentence structure",q:"Which is the adverbial in the sentence below?\n\n\"I will phone you tomorrow evening.\"",type:"mcq",options:["I will","phone","you","tomorrow evening"],answer:"tomorrow evening",explanation:"'Tomorrow evening' tells us when the action will happen — it is an adverbial of time."},
      {id:47,marks:1,topic:"Sentence types",q:"The punctuation has been removed from these sentences. Which one is an exclamation?",type:"mcq",options:["What a delicious meal that was","This meal is delicious","Eat your meal","Is the meal ready"],answer:"What a delicious meal that was",explanation:"A grammatical exclamation starts with 'What' or 'How' and contains a subject and a verb."},
      {id:48,marks:1,topic:"Conjunctions",q:"Which two words are co-ordinating conjunctions in the sentence below?\n\n\"Although it was cold, we wore shorts and T-shirts but took our coats.\"",type:"mcq",options:["Although, and","and, but","Although, but","cold, took"],answer:"and, but",explanation:"Co-ordinating conjunctions (FANBOYS: for, and, nor, but, or, yet, so) join words or clauses of equal status. 'Although' is a subordinating conjunction."},
      {id:49,marks:1,topic:"Word classes",q:"Which two words are adverbs in the sentence below?\n\n\"We often visit the park and play happily on the swings.\"",type:"mcq",options:["often, happily","visit, play","park, swings","often, swings"],answer:"often, happily",explanation:"'Often' tells us how frequently and 'happily' tells us how — both are adverbs."},
      {id:50,marks:1,topic:"Word classes",q:"Which list contains the three determiners in the sentence below?\n\n\"My sister bought a new coat from that shop.\"",type:"mcq",options:["My, a, that","sister, coat, shop","bought, new, from","a, new, from"],answer:"My, a, that",explanation:"Determiners come before a noun and tell us which one or whose: 'My' (sister), 'a' (new coat), 'that' (shop)."}
    ]
  },
  {
    year: "2025",
    questions: [
      {id:1,marks:1,topic:"Word formation",q:"What does the prefix 'sub-' mean in the word 'submarine'?",type:"mcq",options:["under","over","against","again"],answer:"under",explanation:"'Sub-' means under or below: a submarine travels under the sea, a subway goes under the road."},
      {id:2,marks:1,topic:"Vocabulary",q:"Which word is a synonym of 'damp'?",type:"mcq",options:["moist","dry","cold","dark"],answer:"moist",explanation:"'Damp' means slightly wet — 'moist'. 'Dry' is an antonym."},
      {id:3,marks:1,topic:"Punctuation",q:"Which sentence is punctuated correctly?",type:"mcq",options:["\"Can you pass the salt?\" asked Leo.","\"Can you pass the salt\" asked Leo?","\"Can you pass the salt.\" asked Leo?","\"Can you pass the salt,\" asked Leo?"],answer:"\"Can you pass the salt?\" asked Leo.",explanation:"The question mark belongs to the spoken question, so it goes inside the inverted commas. The sentence then ends with a full stop."},
      {id:4,marks:1,topic:"Sentence types",q:"Which sentence is a command?",type:"mcq",options:["Check your answers carefully.","We checked our answers.","The check was quick.","Did you check your answers?"],answer:"Check your answers carefully.",explanation:"A command tells someone to do something and usually starts with an imperative verb: 'Check'."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence uses commas correctly in a list?",type:"mcq",options:["We packed sandwiches, apples, crisps and juice.","We packed, sandwiches apples crisps and juice.","We packed sandwiches apples, crisps, and, juice.","We, packed sandwiches, apples crisps and juice."],answer:"We packed sandwiches, apples, crisps and juice.",explanation:"Commas separate the items in a list. The last two items are joined by 'and'."},
      {id:6,marks:1,topic:"Punctuation",q:"Which punctuation mark could go at the end of this sentence?\n\n\"I can't believe we won the cup\"",type:"mcq",options:["an exclamation mark","a question mark","a comma","a colon"],answer:"an exclamation mark",explanation:"The sentence shows strong feeling (surprise and excitement), so an exclamation mark fits. It is not a question."},
      {id:7,marks:1,topic:"Standard English",q:"Which sentence is written in Standard English?",type:"mcq",options:["They done their homework.","They did their homework.","They have did their homework.","They has done their homework."],answer:"They did their homework.",explanation:"The simple past of 'do' is 'did'. 'Done' needs 'have' (they have done), and 'they' takes 'have', not 'has'."},
      {id:8,marks:1,topic:"Punctuation",q:"Which sentence uses a semi-colon correctly?",type:"mcq",options:["We have been studying the Romans; they built many roads.","We have been; studying the Romans they built many roads.","We have been studying; the Romans they built many roads.","We have been studying the Romans they; built many roads."],answer:"We have been studying the Romans; they built many roads.",explanation:"The semi-colon joins two closely linked main clauses: 'We have been studying the Romans' and 'they built many roads'."},
      {id:9,marks:1,topic:"Sentence types",q:"Which sentence must end with a question mark?",type:"mcq",options:["Did Mia remember her swimming kit","Mia wondered if she had her swimming kit","What a lot of swimming kit Mia has","Mia asked whether we had seen her kit"],answer:"Did Mia remember her swimming kit",explanation:"Only 'Did Mia remember her swimming kit' asks a direct question. The others report a question or are an exclamation."},
      {id:10,marks:1,topic:"Punctuation",q:"Which sentence uses brackets correctly?",type:"mcq",options:["Our teacher (who loves poetry) read us a poem.","Our (teacher who loves poetry) read us a poem.","Our teacher who (loves poetry read) us a poem.","(Our teacher who loves) poetry read us a poem."],answer:"Our teacher (who loves poetry) read us a poem.",explanation:"The brackets surround the extra information 'who loves poetry'. Without it, the sentence still makes sense."},
      {id:11,marks:1,topic:"Formality",q:"Which option completes the sentence in the most formal way?\n\n\"The club was ______ by local volunteers in 2010.\"",type:"mcq",options:["founded","set up","started off","got going"],answer:"founded",explanation:"'Founded' is the formal choice. 'Set up', 'started off' and 'got going' are more informal."},
      {id:12,marks:1,topic:"Sentence structure",q:"Which sentence starts with an adverbial?",type:"mcq",options:["Before breakfast, Sam fed the cat.","Sam fed the cat before breakfast.","The cat was fed by Sam.","Sam, who was hungry, fed the cat."],answer:"Before breakfast, Sam fed the cat.",explanation:"'Before breakfast' is an adverbial (it tells us when). It comes at the start of the sentence, so it is a fronted adverbial."},
      {id:13,marks:1,topic:"Formality",q:"Which sentence is the most formal?",type:"mcq",options:["The meeting will commence at 9am.","Let's kick things off at 9!","We'll get going around 9-ish.","Be there at 9, OK?"],answer:"The meeting will commence at 9am.",explanation:"'Commence' is a formal word, and the sentence has no slang, contractions or casual punctuation."},
      {id:14,marks:1,topic:"Punctuation",q:"Which punctuation could be used instead of the brackets in this sentence?\n\n\"Ben Nevis (the highest mountain in the UK) is in Scotland.\"",type:"mcq",options:["commas","hyphens","colons","semi-colons"],answer:"commas",explanation:"A pair of commas (or dashes) can mark off extra information, just like brackets: 'Ben Nevis, the highest mountain in the UK, is in Scotland.'"},
      {id:15,marks:1,topic:"Punctuation",q:"Which sentence uses a colon correctly?",type:"mcq",options:["We saw three birds on our walk: a robin, a wren and a blackbird.","We saw: three birds on our walk a robin, a wren and a blackbird.","We saw three birds: on our walk a robin, a wren and a blackbird.","We saw three: birds on our walk a robin, a wren and a blackbird."],answer:"We saw three birds on our walk: a robin, a wren and a blackbird.",explanation:"The colon comes after the complete clause 'We saw three birds on our walk' and introduces the list."},
      {id:16,marks:1,topic:"Word classes",q:"Which list contains the three adjectives in this sentence?\n\n\"The ancient tree stood in the quiet, misty valley.\"",type:"mcq",options:["ancient, quiet, misty","tree, valley, stood","the, in, the","ancient, tree, valley"],answer:"ancient, quiet, misty",explanation:"Adjectives describe nouns: 'ancient' describes the tree; 'quiet' and 'misty' describe the valley."},
      {id:17,marks:1,topic:"Punctuation",q:"Which sentence is punctuated correctly?",type:"mcq",options:["Cycling, which is good for your heart and lungs, is great fun.","Cycling which is good, for your heart and lungs, is great fun.","Cycling, which is good for your heart, and lungs is great fun.","Cycling which is good for your heart and lungs is, great fun."],answer:"Cycling, which is good for your heart and lungs, is great fun.",explanation:"The relative clause 'which is good for your heart and lungs' is marked off by a pair of commas."},
      {id:18,marks:1,topic:"Clauses",q:"Use this information to complete the sentence with a relative clause:\n\nMy aunt is a pilot.\n\n\"My aunt, ______, is visiting us next week.\"",type:"short",answer:"who is a pilot",explanation:"A relative clause starting with 'who' adds information about a person: 'My aunt, who is a pilot, is visiting us next week.'"},
      {id:19,marks:1,topic:"Word classes",q:"In which sentence is 'plant' a verb?",type:"mcq",options:["We will plant the seeds tomorrow.","The plant needs more water.","That plant pot is cracked.","A cactus is a desert plant."],answer:"We will plant the seeds tomorrow.",explanation:"In the first sentence, 'plant' is the action (what we will do), so it is a verb. In the others it is a noun or describes a noun."},
      {id:20,marks:1,topic:"Word formation",q:"Which suffix can be added to 'solid' to make a verb?",type:"mcq",options:["-ify","-ness","-ly","-ment"],answer:"-ify",explanation:"solid + ify = solidify (to become solid) — a verb. 'Solidness' is a noun and 'solidly' is an adverb."},
      {id:21,marks:1,topic:"Punctuation",q:"Why is there an apostrophe in the sentence below?\n\n\"The dog's bowl was empty.\"",type:"mcq",options:["to show singular possession","to show plural possession","to show a contraction of 'dog is'","to show a contraction of 'dog has'"],answer:"to show singular possession",explanation:"The bowl belongs to one dog, so the apostrophe shows singular possession (dog's)."},
      {id:22,marks:1,topic:"Punctuation",q:"Which sentence uses a comma after a fronted adverbial?",type:"mcq",options:["As soon as the bell rang, we ran outside.","We bought pens, pencils and rulers.","The tall, friendly teacher waved.","Yes, I would like some more."],answer:"As soon as the bell rang, we ran outside.",explanation:"'As soon as the bell rang' is a fronted adverbial (it says when), so it is followed by a comma. The others use commas in a list, between adjectives, or after 'Yes'."},
      {id:23,marks:1,topic:"Punctuation",q:"Which sentence uses a dash correctly?",type:"mcq",options:["I can't come to the party – I have a swimming gala.","I can't – come to the party I have a swimming gala.","I can't come to – the party I have a swimming gala.","I – can't come to the party I have a swimming gala."],answer:"I can't come to the party – I have a swimming gala.",explanation:"The dash separates two main clauses; the second explains the first."},
      {id:24,marks:1,topic:"Sentence structure",q:"What is the grammatical term for the words in capitals?\n\n\"THE TALL GIRL WITH RED HAIR won the race.\"",type:"mcq",options:["a noun phrase","a relative clause","a preposition phrase","a subordinate clause"],answer:"a noun phrase",explanation:"It is built around the noun 'girl', with words that describe her ('the tall … with red hair'). It has no verb, so it is not a clause."},
      {id:25,marks:1,topic:"Clauses",q:"What type of clause is the part in capitals?\n\n\"I ate my lunch AFTER I FINISHED MY WORK.\"",type:"mcq",options:["a subordinate clause","a main clause","a relative clause","a noun phrase"],answer:"a subordinate clause",explanation:"It starts with the subordinating conjunction 'after' and does not make sense on its own."},
      {id:26,marks:1,topic:"Sentence types",q:"What is the form of this sentence?\n\n\"Don't forget your coat.\"",type:"mcq",options:["command","statement","question","exclamation"],answer:"command",explanation:"It tells someone what to do (or not do), so it is a command."},
      {id:27,marks:1,topic:"Verb forms",q:"Which sentence contains a modal verb?",type:"mcq",options:["You should wear a helmet.","Please pass me the glue.","Where are my shoes?","Ella had been waiting all day."],answer:"You should wear a helmet.",explanation:"'Should' is a modal verb — it shows how likely or necessary something is."},
      {id:28,marks:1,topic:"Sentence structure",q:"Why is the word 'they' unclear in this sentence?\n\n\"When the girls met the new teachers, they were nervous.\"",type:"mcq",options:["It could mean the girls or the new teachers.","It should be 'them' instead.","It is in the wrong tense.","It does not refer to anyone."],answer:"It could mean the girls or the new teachers.",explanation:"'They' could refer to either group, so we cannot tell who was nervous."},
      {id:29,marks:1,topic:"Word formation",q:"Which prefix can be added to all three words to make new words?\n\n___view   ___play   ___turn",type:"mcq",options:["re","dis","un","pre"],answer:"re",explanation:"review, replay, return. The prefix 're-' means again or back."},
      {id:30,marks:1,topic:"Punctuation",q:"Which sentence uses a hyphen correctly?",type:"mcq",options:["My cousin is a world-famous chef.","My cousin is a world famous-chef.","My-cousin is a world famous chef.","My cousin is-a world famous chef."],answer:"My cousin is a world-famous chef.",explanation:"'World-famous' is a compound adjective describing the chef, so the two words are joined with a hyphen."},
      {id:31,marks:1,topic:"Punctuation",q:"Which passage uses inverted commas correctly?",type:"mcq",options:["\"Watch out!\" yelled Tom, pointing at the ice. \"It's very slippery!\"","\"Watch out! yelled Tom, pointing at the ice. It's very slippery!\"","Watch out! \"yelled Tom, pointing at the ice.\" It's very slippery!","\"Watch out!\" yelled Tom, \"pointing at the ice. It's very slippery!\""],answer:"\"Watch out!\" yelled Tom, pointing at the ice. \"It's very slippery!\"",explanation:"Only the words Tom says go inside inverted commas: 'Watch out!' and 'It's very slippery!'."},
      {id:32,marks:1,topic:"Word classes",q:"What is the word class of 'swim' in this sentence?\n\n\"We went for a swim in the lake.\"",type:"mcq",options:["noun","verb","adjective","adverb"],answer:"noun",explanation:"'A swim' is a thing (it follows the determiner 'a'), so here 'swim' is a noun."},
      {id:33,marks:1,topic:"Punctuation",q:"How does the comma change the meaning of the second sentence?\n\n1. Are you ready to eat Grandpa?\n2. Are you ready to eat, Grandpa?",type:"mcq",options:["In sentence 2, Grandpa is being spoken to.","In sentence 2, Grandpa is going to be eaten.","In sentence 2, Grandpa is asking the question.","The comma does not change the meaning."],answer:"In sentence 2, Grandpa is being spoken to.",explanation:"The comma shows that 'Grandpa' is the person being addressed, not the thing being eaten!"},
      {id:34,marks:1,topic:"Clauses",q:"Which part of this sentence is the relative clause?\n\n\"After school, Leo visited the museum, which had just reopened.\"",type:"mcq",options:["which had just reopened","After school","Leo visited the museum","the museum"],answer:"which had just reopened",explanation:"It begins with the relative pronoun 'which' and gives more information about the museum."},
      {id:35,marks:1,topic:"Word classes",q:"Which word is a preposition in this sentence?\n\n\"Priya hid the present under her bed.\"",type:"mcq",options:["under","hid","present","her"],answer:"under",explanation:"'Under' shows where the present was in relation to the bed."},
      {id:36,marks:1,topic:"Sentence structure",q:"What is the subject of this sentence?\n\n\"During the storm, the old tree fell down.\"",type:"mcq",options:["the old tree","the storm","fell","down"],answer:"the old tree",explanation:"The subject is who or what does the verb: the old tree fell."},
      {id:37,marks:1,topic:"Verb forms",q:"Rewrite the sentence below in the passive. Remember to punctuate your answer correctly.\n\n\"Someone painted the door.\"",type:"short",answer:"The door was painted.",accept:["The door was painted by someone."],explanation:"The object ('the door') becomes the subject, and the verb becomes 'was painted'. 'By someone' is usually left out."},
      {id:38,marks:1,topic:"Tense",q:"Complete the sentence with the simple past of the verb 'to catch'.\n\n\"Yesterday, Omar ______ the bus to school.\"",type:"short",answer:"caught",explanation:"'Catch' is irregular: its simple past is 'caught'."},
      {id:39,marks:1,topic:"Word classes",q:"Which list contains the three nouns in this sentence?\n\n\"She sang the song with great joy and never forgot the words.\"",type:"mcq",options:["song, joy, words","sang, forgot, never","great, never, the","she, with, and"],answer:"song, joy, words",explanation:"'Song' and 'words' are things, and 'joy' is an abstract noun (a feeling)."},
      {id:40,marks:1,topic:"Word classes",q:"What is the word class of 'often' in this sentence?\n\n\"We often walk to school.\"",type:"mcq",options:["an adverb","a conjunction","an adjective","a determiner"],answer:"an adverb",explanation:"'Often' tells us how frequently we walk — it modifies the verb, so it is an adverb."},
      {id:41,marks:1,topic:"Sentence structure",q:"Which of these is an expanded noun phrase?",type:"mcq",options:["the small brown puppy","ran quickly","under the table","very happily"],answer:"the small brown puppy",explanation:"An expanded noun phrase has a noun ('puppy') plus words that add detail ('the small brown')."},
      {id:42,marks:1,topic:"Punctuation",q:"Which passage uses capital letters and full stops correctly?",type:"mcq",options:["This year we went to the zoo. My favourite animal was the tiger.","this year we went to the zoo. my favourite animal was the tiger.","This year we went to the zoo my favourite animal was the tiger.","This year. We went to the zoo my favourite animal was the tiger."],answer:"This year we went to the zoo. My favourite animal was the tiger.",explanation:"There are two sentences, so each begins with a capital letter and ends with a full stop."},
      {id:43,marks:1,topic:"Verb forms",q:"Rewrite the sentence below in the active. Remember to punctuate your answer correctly.\n\n\"The cake was eaten by the children.\"",type:"short",answer:"The children ate the cake.",explanation:"In the active, the doer ('the children') becomes the subject: 'The children ate the cake.'"},
      {id:44,marks:1,topic:"Word classes",q:"Which word is a possessive pronoun in this sentence?\n\n\"That red bike is hers, not Tom's.\"",type:"mcq",options:["hers","That","red","bike"],answer:"hers",explanation:"'Hers' shows ownership and stands in place of a noun phrase ('her bike')."},
      {id:45,marks:1,topic:"Conjunctions",q:"Which list contains all the conjunctions in this sentence?\n\n\"Because it was raining, we stayed in and played games until it stopped.\"",type:"mcq",options:["Because, and, until","Because, in, until","and, games, it","raining, stayed, stopped"],answer:"Because, and, until",explanation:"'Because' and 'until' are subordinating conjunctions; 'and' is a co-ordinating conjunction."},
      {id:46,marks:1,topic:"Verb forms",q:"Which word is the verb in the subjunctive?\n\n\"If I were taller, I could reach the top shelf.\"",type:"mcq",options:["were","could","reach","taller"],answer:"were",explanation:"'If I were' (instead of 'if I was') is the subjunctive, used for imagined situations."},
      {id:47,marks:1,topic:"Word classes",q:"Which list contains the three determiners in this sentence?\n\n\"There are some apples in that bowl but no bananas.\"",type:"mcq",options:["some, that, no","apples, bowl, bananas","are, in, but","There, some, but"],answer:"some, that, no",explanation:"Determiners come before nouns: 'some' (apples), 'that' (bowl), 'no' (bananas)."},
      {id:48,marks:1,topic:"Verb forms",q:"Complete the sentence using the past progressive form of the verb 'to walk'.\n\n\"While we ______ home, it started to snow.\"",type:"short",answer:"were walking",explanation:"The past progressive is was/were + -ing: 'we were walking'."},
      {id:49,marks:1,topic:"Word classes",q:"Which word is an adverb in this sentence?\n\n\"Although the path was steep, the hikers climbed steadily to the top.\"",type:"mcq",options:["steadily","steep","Although","top"],answer:"steadily",explanation:"'Steadily' describes how the hikers climbed — it is an adverb."},
      {id:50,marks:1,topic:"Verb forms",q:"Complete the sentence using the past perfect form of the verb 'to finish'.\n\n\"By the time Dad arrived, we ______ our dinner.\"",type:"short",answer:"had finished",explanation:"The past perfect is 'had' + past participle: 'had finished'. It shows we finished before Dad arrived."}
    ]
  },
  {
    year: "2024",
    questions: [
      {id:1,marks:1,topic:"Word classes",q:"Which word is a verb in this sentence?\n\n\"The excited children rushed into the classroom.\"",type:"mcq",options:["excited","children","rushed","classroom"],answer:"rushed",explanation:"A verb is a doing or being word. 'Rushed' is the action the children performed. 'Excited' is an adjective; 'children' and 'classroom' are nouns."},
      {id:2,marks:1,topic:"Punctuation",q:"Which sentence uses a semi-colon correctly?",type:"mcq",options:["It was cold outside; she put on her coat.","It was cold; outside she put on her coat.","It was; cold outside she put on her coat.","It was cold outside she; put on her coat."],answer:"It was cold outside; she put on her coat.",explanation:"A semi-colon joins two independent clauses of equal weight. Both 'It was cold outside' and 'she put on her coat' are complete sentences — they are closely related and balanced in importance."},
      {id:3,marks:1,topic:"Sentence types",q:"Which sentence is a command?",type:"mcq",options:["The dog is barking.","Is the dog barking?","Stop that dog from barking!","What a noise that dog is making!"],answer:"Stop that dog from barking!",explanation:"A command gives an instruction or order. It starts with a verb ('Stop'). Note: exclamations start with 'What' or 'How'. The example 'What a noise...' is an exclamation, not a command."},
      {id:4,marks:1,topic:"Conjunctions",q:"Which conjunction shows cause in this sentence?\n\n\"She missed the bus _______ she overslept.\"",type:"mcq",options:["although","because","but","whereas"],answer:"because",explanation:"'Because' introduces a reason or cause — she missed the bus as a result of oversleeping. 'Although' and 'but' show contrast; 'whereas' shows comparison."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence punctuates a fronted adverbial correctly?",type:"mcq",options:["Slowly and carefully, she opened the door.","Slowly and carefully she, opened the door.","Slowly, and carefully she opened the door.","Slowly and carefully she opened, the door."],answer:"Slowly and carefully, she opened the door.",explanation:"A fronted adverbial is a phrase at the start of a sentence that tells us how, when, or where. It must be followed by a comma before the main clause begins."},
      {id:6,marks:1,topic:"Verb forms",q:"Which sentence is written in the present perfect tense?",type:"mcq",options:["She painted the fence.","She is painting the fence.","She has painted the fence.","She will paint the fence."],answer:"She has painted the fence.",explanation:"Present perfect = has/have + past participle ('has painted'). It describes an action completed at an unspecified time before now. Option A = simple past; B = present progressive; D = future simple."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence uses a dash correctly to add extra information?",type:"mcq",options:["The winner — Jamie — received a gold trophy.","The winner Jamie — received a gold trophy.","The winner — Jamie received a gold trophy.","The — winner Jamie received a gold trophy."],answer:"The winner — Jamie — received a gold trophy.",explanation:"Dashes can be used in pairs to add parenthetical information (like brackets). Both dashes must be present: before and after 'Jamie'."},
      {id:8,marks:1,topic:"Word classes",q:"What is the grammatical term for the underlined word?\n\n\"She walked across the bridge.\"  (across)",type:"mcq",options:["Conjunction","Preposition","Adverb","Adjective"],answer:"Preposition",explanation:"A preposition shows the relationship between a noun/pronoun and another word, often indicating place, direction or time. 'Across' shows the direction of her movement in relation to 'the bridge'."},
      {id:9,marks:1,topic:"Spelling",q:"Choose the correct spelling:",type:"mcq",options:["necesary","neccesary","necessary","necessery"],answer:"necessary",explanation:"'Necessary' — one collar (c) and two socks (ss): n-e-c-e-s-s-a-r-y. A useful memory trick: it has one C and two S letters."},
      {id:10,marks:1,topic:"Punctuation",q:"Tick the sentence that correctly punctuates direct speech.",type:"mcq",options:["\"I love football\" said Marcus.","\"I love football,\" said Marcus.","\"I love football\", said Marcus.","\"I love football.\" said Marcus."],answer:"\"I love football,\" said Marcus.",explanation:"When the reporting clause follows speech, use a comma (not a full stop) inside the closing speech mark. The correct form: \"I love football,\" said Marcus."},
      {id:11,marks:1,topic:"Clauses",q:"Which sentence contains an embedded relative clause?",type:"mcq",options:["The cat, which was black, sat on the mat.","The cat sat on the mat and it was black.","The black cat sat on the mat.","The cat sat on the mat although it was black."],answer:"The cat, which was black, sat on the mat.",explanation:"A relative clause beginning with 'which', 'who' or 'that' is embedded (inserted) within the main clause using commas. 'which was black' is embedded between commas."},
      {id:12,marks:1,topic:"Word classes",q:"Which word is an abstract noun?",type:"mcq",options:["table","happiness","quickly","jump"],answer:"happiness",explanation:"An abstract noun names something you cannot physically touch or see — a concept, feeling, or idea. 'Happiness' is a feeling. 'Table' = concrete noun; 'quickly' = adverb; 'jump' = verb."},
      {id:13,marks:1,topic:"Punctuation",q:"Which sentence correctly uses a colon to introduce a list?",type:"mcq",options:["She packed: her coat, boots and umbrella.","She packed her coat: boots and umbrella.","She packed her coat, boots: and umbrella.","She: packed her coat, boots and umbrella."],answer:"She packed: her coat, boots and umbrella.",explanation:"A colon introduces a list after a complete clause. 'She packed' is a complete clause — the colon then introduces what she packed. A colon should not interrupt the flow of the main clause."},
      {id:14,marks:1,topic:"Sentence structure",q:"Which sentence is an example of an exclamation?",type:"mcq",options:["Run as fast as you can!","What a brilliant performance that was!","Stop making so much noise!","Did you enjoy the show?"],answer:"What a brilliant performance that was!",explanation:"A grammatical exclamation must begin with 'What' or 'How', contain a subject and verb, and end with an exclamation mark. Only option B meets all criteria."},
      {id:15,marks:1,topic:"Word classes",q:"What is the word class of 'joyfully' in this sentence?\n\n\"The children joyfully accepted the gift.\"",type:"mcq",options:["Adjective","Adverb","Noun","Verb"],answer:"Adverb",explanation:"'Joyfully' is an adverb — it modifies the verb 'accepted', telling us HOW the children accepted the gift. Most adverbs of manner end in '-ly'."},
      {id:16,marks:1,topic:"Punctuation",q:"Where does the apostrophe go in this phrase?\n\nThe womens changing room",type:"mcq",options:["women's changing room","womens' changing room","womens changing room'","women'S changing room"],answer:"women's changing room",explanation:"'Women' is an irregular plural (doesn't end in -s). For irregular plurals, add apostrophe + s: women's. Compare 'girls' (regular plural) → girls' changing room."},
      {id:17,marks:1,topic:"Vocabulary",q:"Which word is an antonym of 'generous'?",type:"mcq",options:["kind","charitable","mean","giving"],answer:"mean",explanation:"An antonym is a word with the opposite meaning. 'Generous' means willing to give freely. 'Mean' means unwilling to share or give — the opposite. 'Kind' and 'charitable' are synonyms."},
      {id:18,marks:1,topic:"Tense",q:"Rewrite this sentence in the passive voice:\n\n\"The gardener planted the flowers.\"",type:"short",answer:"The flowers were planted by the gardener.",explanation:"Passive voice: the object ('the flowers') becomes the subject. Use 'to be' + past participle: 'were planted'. The original agent becomes a 'by' phrase: 'by the gardener'."},
      {id:19,marks:1,topic:"Punctuation",q:"Which option correctly uses brackets for parenthesis?",type:"mcq",options:["The Eiffel Tower (built in 1889) is in Paris.","The Eiffel Tower built (in 1889) is in Paris.","The (Eiffel Tower built in 1889) is in Paris.","The Eiffel Tower built in (1889 is in Paris.)"],answer:"The Eiffel Tower (built in 1889) is in Paris.",explanation:"Brackets add extra, non-essential information to a sentence. The information inside must be removable without changing the core meaning. 'built in 1889' is the extra detail here."},
      {id:20,marks:1,topic:"Formal/informal",q:"Which sentence uses the subjunctive mood correctly?",type:"mcq",options:["If I was you, I would apologise.","If I were you, I would apologise.","If I am you, I would apologise.","If I be you, I would apologise."],answer:"If I were you, I would apologise.",explanation:"The subjunctive mood is used for hypothetical or contrary-to-fact conditions. 'If I were you' (not 'was') is the correct subjunctive form — it expresses an imaginary condition."}
    ]
  },
  {
    year: "2023",
    questions: [
      {id:1,marks:1,topic:"Word classes",q:"Which word in this sentence is a pronoun?\n\n\"They left their bags by the door.\"",type:"mcq",options:["They","left","bags","door"],answer:"They",explanation:"A pronoun stands in place of a noun. 'They' replaces the name of a group of people. 'Left' is a verb; 'bags' and 'door' are nouns."},
      {id:2,marks:1,topic:"Punctuation",q:"Which sentence uses hyphens correctly to create a compound adjective?",type:"mcq",options:["She wore a well-known dress.","She wore a well known dress.","She wore a wellknown dress.","She wore a well, known dress."],answer:"She wore a well-known dress.",explanation:"Compound adjectives used before a noun are hyphenated: well-known. Without the hyphen, 'well' could be read as a separate adverb. If used after the noun, no hyphen is needed (e.g. 'The dress was well known')."},
      {id:3,marks:1,topic:"Sentence types",q:"Which sentence is a statement?",type:"mcq",options:["Put your pen down.","Have you finished your work?","I have finished my work.","What a long piece of work that was!"],answer:"I have finished my work.",explanation:"A statement gives information and ends with a full stop. Option A is a command; B is a question; D is an exclamation."},
      {id:4,marks:1,topic:"Conjunctions",q:"Which subordinating conjunction best completes this sentence?\n\n\"He continued to play _______ he was injured.\"",type:"mcq",options:["because","so","even though","therefore"],answer:"even though",explanation:"'Even though' introduces a concessive clause — the action continued despite the obstacle (the injury). 'Because' shows cause; 'so' shows result; 'therefore' is a connective, not a conjunction."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence uses commas correctly in a list?",type:"mcq",options:["She bought apples, pears, bananas, and grapes.","She bought apples pears, bananas and grapes.","She bought, apples, pears, bananas and grapes.","She bought apples, pears bananas and grapes."],answer:"She bought apples, pears, bananas, and grapes.",explanation:"Commas separate items in a list. Each item is followed by a comma (the final comma before 'and' is called an Oxford comma — accepted in KS2). No comma before the first item."},
      {id:6,marks:1,topic:"Verb forms",q:"Which sentence uses the future perfect tense?",type:"mcq",options:["She will sing tomorrow.","She is singing now.","She has sung already.","She will have sung by noon."],answer:"She will have sung by noon.",explanation:"Future perfect = will have + past participle ('will have sung'). It describes an action that will be completed before a specific future time. Option A = future simple; C = present perfect."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence uses an ellipsis correctly?",type:"mcq",options:["She opened the door and... screamed.","She opened... the door and screamed.","...She opened the door and screamed.","She opened the door and screamed..."],answer:"She opened the door and... screamed.",explanation:"An ellipsis (...) can create dramatic pause or suspense within a sentence. Placing it before the climax ('screamed') builds tension effectively."},
      {id:8,marks:1,topic:"Word classes",q:"Which sentence contains a modal verb?",type:"mcq",options:["She runs every morning.","She could run faster than anyone.","She ran a marathon last year.","She is running in the race."],answer:"She could run faster than anyone.",explanation:"Modal verbs express possibility, ability, permission or obligation: can, could, may, might, shall, should, will, would, must. 'Could' is a modal verb indicating ability."},
      {id:9,marks:1,topic:"Spelling",q:"Choose the correct spelling:",type:"mcq",options:["recieve","recievve","receive","receeve"],answer:"receive",explanation:"'Receive' follows the rule 'i before e except after c': r-e-c-e-i-v-e. After the letter 'c', use 'ei' not 'ie'."},
      {id:10,marks:1,topic:"Punctuation",q:"Which is the correct punctuation for this sentence?\n\n\"Weve been waiting for an hour said Priya\"",type:"mcq",options:["\"We've been waiting for an hour,\" said Priya.","\"Weve been waiting for an hour,\" said Priya.","\"We've been waiting for an hour\" said Priya.","\"We've been waiting for an hour.\" said Priya."],answer:"\"We've been waiting for an hour,\" said Priya.",explanation:"The apostrophe in 'We've' (contraction of 'we have') is essential. The comma goes inside the closing speech mark. The reporting clause 'said Priya' starts with a lower-case letter."},
      {id:11,marks:1,topic:"Clauses",q:"Which part of this sentence is the subordinate clause?\n\n\"Although the rain was heavy, they finished the match.\"",type:"mcq",options:["Although the rain was heavy","they finished the match","the rain was heavy","Although"],answer:"Although the rain was heavy",explanation:"A subordinate clause cannot stand alone as a sentence — it depends on the main clause for meaning. 'Although the rain was heavy' makes incomplete sense on its own."},
      {id:12,marks:1,topic:"Word classes",q:"Which sentence contains a determiner?",type:"mcq",options:["She runs fast.","The dog barked loudly.","He shouted angrily.","They left quickly."],answer:"The dog barked loudly.",explanation:"A determiner comes before a noun to introduce it: the, a, an, this, that, these, those, my, his, her, some, any. 'The' is a determiner before 'dog'."},
      {id:13,marks:1,topic:"Punctuation",q:"Which sentence uses inverted commas correctly for a title?",type:"mcq",options:["She read 'The Midnight Fox' in one evening.","She read the Midnight Fox in one evening.","She read \"the Midnight Fox\" in one evening.","She read The Midnight Fox in one evening."],answer:"She read 'The Midnight Fox' in one evening.",explanation:"Titles of books, films or works are placed in inverted commas (single or double). The title words are capitalised."},
      {id:14,marks:1,topic:"Sentence structure",q:"Which sentence uses a fronted adverbial?",type:"mcq",options:["She quietly tiptoed down the stairs.","Down the stairs, she quietly tiptoed.","She tiptoed quietly down the stairs.","She tiptoed down the stairs quietly."],answer:"Down the stairs, she quietly tiptoed.",explanation:"A fronted adverbial is an adverbial phrase placed at the front of the sentence, followed by a comma. 'Down the stairs,' is the fronted adverbial here."},
      {id:15,marks:1,topic:"Word classes",q:"Identify the preposition in this sentence:\n\n\"The letter was hidden beneath the floorboard.\"",type:"mcq",options:["hidden","beneath","floorboard","letter"],answer:"beneath",explanation:"'Beneath' is a preposition showing the position of the letter in relation to the floorboard. It indicates place/position."},
      {id:16,marks:1,topic:"Punctuation",q:"Which sentence uses an apostrophe for omission correctly?",type:"mcq",options:["I ca'nt believe it's raining again.","I can't believe its raining again.","I can't believe it's raining again.","I cant believe it's raining again."],answer:"I can't believe it's raining again.",explanation:"'Can't' = cannot (apostrophe replaces 'no'). 'It's' = it is (apostrophe replaces 'i'). Both contractions need apostrophes. 'Its' without apostrophe is possessive (e.g. the dog wagged its tail)."},
      {id:17,marks:1,topic:"Vocabulary",q:"Which word is a synonym for 'abundant'?",type:"mcq",options:["scarce","plentiful","empty","rare"],answer:"plentiful",explanation:"'Abundant' means existing in large quantities. 'Plentiful' is its synonym. 'Scarce', 'rare' and 'empty' all suggest the opposite — small or no quantity."},
      {id:18,marks:1,topic:"Tense",q:"Rewrite this sentence using the passive voice:\n\n\"The wind blew down the old oak tree.\"",type:"short",answer:"The old oak tree was blown down by the wind.",explanation:"Passive: object ('the old oak tree') becomes subject. Use 'to be' + past participle: 'was blown down'. Agent: 'by the wind'. Note: past tense of 'blow' = 'blown' (irregular verb)."},
      {id:19,marks:1,topic:"Punctuation",q:"Which option is punctuated correctly?",type:"mcq",options:["My three favourite subjects are: maths, science and English.","My three favourite subjects are maths science and English.","My three favourite: subjects are maths, science and English.","My three favourite subjects are; maths, science and English."],answer:"My three favourite subjects are: maths, science and English.",explanation:"A colon after a complete clause introduces a list. 'My three favourite subjects are' is a complete clause — the colon then introduces the list."},
      {id:20,marks:1,topic:"Formal/informal",q:"Which sentence is in the most formal register?",type:"mcq",options:["Thanks for getting back to me so quick!","Cheers for the speedy reply!","I am grateful for your prompt response.","Got your message — cheers!"],answer:"I am grateful for your prompt response.",explanation:"Formal register uses complete sentences, standard vocabulary and no contractions or colloquialisms. Option C uses formal vocabulary ('grateful', 'prompt response') and no informal language."}
    ]
  },
  {
    year: "2022",
    questions: [
      {id:1,marks:1,topic:"Word classes",q:"Which word is an adjective in this sentence?\n\n\"The enormous wave crashed against the rocky cliff.\"",type:"mcq",options:["crashed","enormous","against","cliff"],answer:"enormous",explanation:"An adjective describes a noun. 'Enormous' describes the wave. 'Crashed' is a verb; 'against' is a preposition; 'cliff' is a noun. (Note: 'rocky' is also an adjective but is not listed as an option.)"},
      {id:2,marks:1,topic:"Punctuation",q:"Which sentence uses a colon correctly?",type:"mcq",options:["He had one goal: to win the championship.","He had: one goal to win the championship.","He had one: goal to win the championship.","He: had one goal to win the championship."],answer:"He had one goal: to win the championship.",explanation:"A colon follows a complete main clause and introduces an explanation or elaboration. 'He had one goal' is a complete clause; the colon then reveals what that goal was."},
      {id:3,marks:1,topic:"Sentence types",q:"Which is an example of a rhetorical question?",type:"mcq",options:["What time does the film start?","Have you tidied your room?","Who could forget that glorious summer?","Where did you put my keys?"],answer:"Who could forget that glorious summer?",explanation:"A rhetorical question is asked for effect — no answer is expected. 'Who could forget that glorious summer?' implies everyone remembers it and is used for emphasis, not to seek information."},
      {id:4,marks:1,topic:"Conjunctions",q:"Choose the correct coordinating conjunction:\n\n\"She wanted to stay up late _______ her parents said no.\"",type:"mcq",options:["because","although","but","since"],answer:"but",explanation:"Coordinating conjunctions join two equally weighted clauses (FANBOYS: for, and, nor, but, or, yet, so). 'But' shows contrast here. 'Because', 'although' and 'since' are subordinating conjunctions."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence uses commas correctly around a relative clause?",type:"mcq",options:["The book which I borrowed, was fascinating.","The book, which I borrowed, was fascinating.","The book, which I borrowed was fascinating.","The book which, I borrowed, was fascinating."],answer:"The book, which I borrowed, was fascinating.",explanation:"A non-defining relative clause (extra information not essential to the meaning) is enclosed in commas. 'Which I borrowed' is non-defining — it adds detail but removing it leaves the core meaning intact."},
      {id:6,marks:1,topic:"Verb forms",q:"Which sentence is written in the past progressive tense?",type:"mcq",options:["She sang beautifully.","She has sung the song.","She was singing when the phone rang.","She sings every day."],answer:"She was singing when the phone rang.",explanation:"Past progressive = was/were + present participle (-ing form). It describes an ongoing action in the past, often interrupted by another event ('when the phone rang')."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence uses parenthetical commas correctly?",type:"mcq",options:["My teacher, Mrs Green is very kind.","My teacher Mrs Green, is very kind.","My teacher, Mrs Green, is very kind.","My, teacher Mrs Green, is very kind."],answer:"My teacher, Mrs Green, is very kind.",explanation:"Parenthetical commas come in pairs to enclose non-essential information. 'Mrs Green' is extra identifying information — it can be removed without changing the main meaning ('My teacher is very kind')."},
      {id:8,marks:1,topic:"Word classes",q:"Which sentence uses an adverbial phrase of time?",type:"mcq",options:["She ran quickly down the road.","She ran every morning before school.","She ran to the park.","She ran because she was late."],answer:"She ran every morning before school.",explanation:"'Every morning before school' is an adverbial phrase of time — it tells us WHEN she ran. Option A = manner; C = place; D = reason (subordinate clause)."},
      {id:9,marks:1,topic:"Spelling",q:"Choose the correct spelling:",type:"mcq",options:["accomodation","accommodation","accomadation","acomodation"],answer:"accommodation",explanation:"'Accommodation' has double c and double m: a-c-c-o-m-m-o-d-a-t-i-o-n. Memory tip: it has enough room for 2 cots and 2 mattresses (double c, double m)!"},
      {id:10,marks:1,topic:"Punctuation",q:"Which sentence is correctly punctuated?",type:"mcq",options:["\"Don't touch that!\" she warned.","\"Don't touch that\" she warned.","\"Don't touch that!\" She warned.","\"don't touch that!\" she warned."],answer:"\"Don't touch that!\" she warned.",explanation:"After an exclamation mark inside speech marks, the reporting clause ('she warned') starts with a lower case letter. The first word of speech is capitalised."},
      {id:11,marks:1,topic:"Clauses",q:"How many clauses does this sentence contain?\n\n\"Although it was cold, I went for a walk because I needed fresh air.\"",type:"mcq",options:["One","Two","Three","Four"],answer:"Three",explanation:"Clause 1: 'Although it was cold' (subordinate); Clause 2: 'I went for a walk' (main); Clause 3: 'because I needed fresh air' (subordinate). Three clauses total."},
      {id:12,marks:1,topic:"Word classes",q:"Which word is a conjunction in this sentence?\n\n\"She was tired yet she kept working.\"",type:"mcq",options:["tired","yet","working","kept"],answer:"yet",explanation:"'Yet' here is a coordinating conjunction meaning 'but' or 'nevertheless', joining two contrasting clauses. It can also be an adverb of time ('not yet'), but here it functions as a conjunction."},
      {id:13,marks:1,topic:"Punctuation",q:"Which sentence uses a question mark correctly?",type:"mcq",options:["I wonder if it will rain tomorrow?","She asked whether I had finished?","Can you help me with this problem?","He wanted to know what time it was?"],answer:"Can you help me with this problem?",explanation:"Only direct questions need a question mark. 'Can you help me' is a direct question addressed to someone. The other options are indirect questions (reported speech/thoughts) — these don't need question marks."},
      {id:14,marks:1,topic:"Sentence structure",q:"Which technique does this sentence use?\n\n\"Not only did she win the race, but she also broke the record.\"",type:"mcq",options:["Passive voice","Fronted adverbial","Inverted sentence structure","Relative clause"],answer:"Inverted sentence structure",explanation:"Starting with 'Not only' creates an inverted structure — the auxiliary verb 'did' comes before the subject 'she'. This is a deliberate stylistic choice for emphasis."},
      {id:15,marks:1,topic:"Word classes",q:"Which word is a possessive pronoun in this sentence?\n\n\"The red bag is mine.\"",type:"mcq",options:["red","bag","is","mine"],answer:"mine",explanation:"Possessive pronouns show ownership without needing a noun after them: mine, yours, his, hers, its, ours, theirs. 'Mine' replaces 'my bag'. Compare possessive adjectives (my, your, his) which come before a noun."},
      {id:16,marks:1,topic:"Punctuation",q:"Which option shows the correct use of an apostrophe in a plural possessive?",type:"mcq",options:["The teachers' staff room was repainted.","The teacher's' staff room was repainted.","The teachers's staff room was repainted.","The teachers staff room was repainted."],answer:"The teachers' staff room was repainted.",explanation:"For regular plurals ending in -s, add only an apostrophe after the -s: teachers'. This shows that many teachers share the staff room."},
      {id:17,marks:1,topic:"Vocabulary",q:"Which word is closest in meaning to 'transparent'?",type:"mcq",options:["dark","clear","solid","rough"],answer:"clear",explanation:"'Transparent' means see-through or easy to see through. 'Clear' is the closest synonym (e.g. clear glass). 'Dark' and 'solid' are opposites; 'rough' refers to texture."},
      {id:18,marks:1,topic:"Tense",q:"Rewrite this sentence in the simple future tense:\n\n\"She was reading the report.\"",type:"short",answer:"She will read the report.",explanation:"Simple future = will + base form of verb. 'Was reading' (past progressive) → 'will read' (future simple). Do not write 'will be reading' — that is the future progressive tense."},
      {id:19,marks:1,topic:"Punctuation",q:"Which sentence uses a semi-colon correctly to separate items in a complex list?",type:"mcq",options:["We visited Paris, France; Rome, Italy; and Berlin, Germany.","We visited Paris, France, Rome, Italy, and Berlin, Germany.","We visited: Paris, France; Rome, Italy; and Berlin, Germany.","We visited Paris; France, Rome; Italy, and Berlin; Germany."],answer:"We visited Paris, France; Rome, Italy; and Berlin, Germany.",explanation:"Semi-colons can separate items in a list when the items themselves contain commas. This avoids confusion — each destination (city + country) is kept together."},
      {id:20,marks:1,topic:"Formal/informal",q:"Rewrite this informal sentence in formal English:\n\n\"Kids nowadays don't wanna read books.\"",type:"short",answer:"Children today do not wish to read books.",explanation:"Formal English: replace 'Kids' with 'Children', 'nowadays' with 'today', expand 'don't' to 'do not', and replace informal 'wanna' with 'wish to'. Avoid slang and contractions."}
    ]
  },
  {
    year: "2019",
    questions: [
      {id:1,marks:1,topic:"Word classes",q:"Which word is a noun in this sentence?\n\n\"The fierce wind rattled the windows.\"",type:"mcq",options:["fierce","wind","rattled","windows"],answer:"wind",explanation:"'Wind' is a noun — it names a thing. 'Windows' is also a noun but is not listed. 'Fierce' is an adjective; 'rattled' is a verb."},
      {id:2,marks:1,topic:"Punctuation",q:"Which sentence uses an apostrophe correctly?",type:"mcq",options:["Its going to rain today.","It's going to rain today.","It's going to rain to'day.","Its' going to rain today."],answer:"It's going to rain today.",explanation:"'It's' is the contraction of 'it is'. The apostrophe replaces the letter 'i'. 'Its' without apostrophe is the possessive pronoun (e.g. the cat licked its paw)."},
      {id:3,marks:1,topic:"Sentence types",q:"What punctuation mark should end this sentence?\n\n\"What a fantastic goal that was\"",type:"mcq",options:["Full stop (.)","Question mark (?)","Exclamation mark (!)","Comma (,)"],answer:"Exclamation mark (!)",explanation:"This is an exclamation — it starts with 'What' and contains a subject ('that') and verb ('was'). Exclamations end with an exclamation mark."},
      {id:4,marks:1,topic:"Conjunctions",q:"Which sentence uses a subordinating conjunction correctly?",type:"mcq",options:["She cried and laughed at the same time.","She laughed, but she was crying inside.","She laughed until the tears rolled down her face.","She laughed or cried — she wasn't sure which."],answer:"She laughed until the tears rolled down her face.",explanation:"'Until' is a subordinating conjunction that introduces a subordinate clause of time. 'And' and 'but' and 'or' are coordinating conjunctions joining equal clauses."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence uses a colon correctly to introduce an explanation?",type:"mcq",options:["There was only one problem: the key had snapped in the lock.","There was: only one problem the key had snapped in the lock.","There was only: one problem the key had snapped in the lock.","There was only one problem the key: had snapped in the lock."],answer:"There was only one problem: the key had snapped in the lock.",explanation:"A colon after a complete clause introduces an explanation. 'There was only one problem' is the complete main clause; the colon then reveals what that problem was."},
      {id:6,marks:1,topic:"Verb forms",q:"Which sentence uses a modal verb to express obligation?",type:"mcq",options:["She can swim very well.","She might go to the party.","She must complete the form today.","She will arrive tomorrow."],answer:"She must complete the form today.",explanation:"'Must' expresses strong obligation or necessity — there is no choice. 'Can' = ability; 'might' = possibility; 'will' = future certainty."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence uses bullet points correctly?",type:"mcq",options:["The rules are:\n• No running\n• No shouting\n• No eating in class","The rules are\n• No running.\n• No shouting.\n• No eating in class.","The rules, are:\n• No running\n• No shouting\n• No eating in class","The rules are:\n• no running\n• no shouting\n• no eating in class"],answer:"The rules are:\n• No running\n• No shouting\n• No eating in class",explanation:"A colon introduces the list. Each bullet point starts with a capital letter (when they are short phrases). No full stops are needed at the end of short bullet-point phrases."},
      {id:8,marks:1,topic:"Word classes",q:"Which word is used as an adverb in this sentence?\n\n\"She sang so beautifully that everyone cried.\"",type:"mcq",options:["sang","so","beautifully","cried"],answer:"beautifully",explanation:"'Beautifully' is an adverb modifying the verb 'sang' (telling us HOW she sang). 'So' is also an adverb here (modifying 'beautifully') but 'beautifully' is the primary adverb answer expected."},
      {id:9,marks:1,topic:"Spelling",q:"Choose the correct spelling:",type:"mcq",options:["concious","consciuous","conscious","consciuos"],answer:"conscious",explanation:"'Conscious' is spelled: c-o-n-s-c-i-o-u-s. Note the 'sc' in the middle and the ending '-ious'. Related word: conscience."},
      {id:10,marks:1,topic:"Punctuation",q:"Which sentence uses capital letters correctly?",type:"mcq",options:["my favourite subject is english and maths.","My favourite subject is English and Maths.","My favourite subject is english and maths.","my Favourite Subject is English and Maths."],answer:"My favourite subject is English and Maths.",explanation:"Capital letters are needed at the start of sentences and for proper nouns. 'English' and 'Maths' are subject names and are capitalised. Common nouns and adjectives like 'favourite' and 'subject' do not get capitals mid-sentence."},
      {id:11,marks:1,topic:"Clauses",q:"Which type of clause is underlined?\n\n\"She read the letter that had arrived that morning.\"  (that had arrived that morning)",type:"mcq",options:["Main clause","Subordinate adverbial clause","Relative clause","Coordinate clause"],answer:"Relative clause",explanation:"'That had arrived that morning' begins with the relative pronoun 'that' and gives more information about 'the letter'. This makes it a relative clause."},
      {id:12,marks:1,topic:"Word classes",q:"Which sentence contains a proper noun?",type:"mcq",options:["The city is very busy.","London is a very busy city.","The capital city is very busy.","Every city has busy streets."],answer:"London is a very busy city.",explanation:"A proper noun is the specific name of a person, place or thing — it always starts with a capital letter. 'London' is a proper noun. 'City', 'capital' and 'streets' are common nouns."},
      {id:13,marks:1,topic:"Punctuation",q:"Add the correct punctuation to complete this sentence:\n\n\"Oh no _____ I've left my bag on the bus___\"",type:"mcq",options:["Oh no, I've left my bag on the bus!","Oh no! I've left my bag on the bus.","Oh no! I've left my bag on the bus!","Oh no. I've left my bag on the bus!"],answer:"Oh no! I've left my bag on the bus!",explanation:"'Oh no!' is an interjection expressing alarm — it needs an exclamation mark. The second sentence also conveys strong feeling/urgency, so an exclamation mark fits. Both exclamation marks are acceptable."},
      {id:14,marks:1,topic:"Sentence structure",q:"Which sentence uses a conditional clause?",type:"mcq",options:["She went to school despite the rain.","If she studies hard, she will pass the exam.","She studied hard and passed the exam.","She passed the exam because she had studied hard."],answer:"If she studies hard, she will pass the exam.",explanation:"A conditional clause (often beginning with 'if' or 'unless') describes a condition and its consequence. 'If she studies hard' is the condition; 'she will pass' is the result."},
      {id:15,marks:1,topic:"Word classes",q:"What type of word is 'however' in this sentence?\n\n\"She wanted to go; however, it was too late.\"",type:"mcq",options:["Conjunction","Adverb","Preposition","Determiner"],answer:"Adverb",explanation:"'However' is a conjunctive adverb — it connects two ideas (like a conjunction) but functions grammatically as an adverb. It is preceded by a semi-colon and followed by a comma."},
      {id:16,marks:1,topic:"Punctuation",q:"Which sentence correctly uses an apostrophe with a singular proper noun?",type:"mcq",options:["James' book was on the shelf.","James's book was on the shelf.","Jamess book was on the shelf.","Jame's book was on the shelf."],answer:"James's book was on the shelf.",explanation:"For singular nouns ending in -s, add apostrophe + s: James's. Both 'James's' and 'James'' are accepted in English, but in KS2 SATs, 'James's' is the preferred form."},
      {id:17,marks:1,topic:"Vocabulary",q:"Which word is a synonym for 'timid'?",type:"mcq",options:["bold","shy","brave","noisy"],answer:"shy",explanation:"'Timid' means lacking confidence or easily frightened. 'Shy' is its closest synonym. 'Bold' and 'brave' are antonyms; 'noisy' is unrelated to character confidence."},
      {id:18,marks:1,topic:"Tense",q:"Rewrite this sentence in the present perfect tense:\n\n\"She visited Paris three times.\"",type:"short",answer:"She has visited Paris three times.",explanation:"Present perfect = has/have + past participle. 'Visited' (simple past) → 'has visited' (present perfect). This implies she has been there before and the relevance to the present is implied."},
      {id:19,marks:1,topic:"Punctuation",q:"Which sentence is correctly punctuated?",type:"mcq",options:["The shop which opened last year sells fresh bread, cakes and coffee.","The shop, which opened last year, sells fresh bread, cakes and coffee.","The shop which opened last year, sells fresh bread cakes and coffee.","The shop which, opened last year, sells fresh bread, cakes and coffee."],answer:"The shop, which opened last year, sells fresh bread, cakes and coffee.",explanation:"The relative clause 'which opened last year' is non-defining — it adds extra information but is not essential. It must be enclosed in commas. The list also uses commas correctly."},
      {id:20,marks:1,topic:"Formal/informal",q:"Which sentence is written in an impersonal, formal style?",type:"mcq",options:["You should eat more fruit and veg.","It is recommended that people increase their consumption of fruit and vegetables.","Eat more fruit and veg — it's good for you!","Everyone should eat their five a day."],answer:"It is recommended that people increase their consumption of fruit and vegetables.",explanation:"Formal, impersonal writing uses the passive voice ('It is recommended'), avoids direct address ('you'), uses full vocabulary ('consumption', 'vegetables') and no contractions or colloquialisms."}
    ]
  },
  {
    year: "2018",
    questions: [
      {id:1,marks:1,topic:"Word classes",q:"Which word is an adverb in this sentence?\n\n\"The dog barked loudly outside the door.\"",type:"mcq",options:["dog","loudly","outside","door"],answer:"loudly",explanation:"'Loudly' is an adverb modifying the verb 'barked' — it tells us HOW the dog barked. 'Outside' here is a preposition; 'dog' and 'door' are nouns."},
      {id:2,marks:1,topic:"Punctuation",q:"Which sentence uses apostrophes correctly?",type:"mcq",options:["The boys' football rolled into the neighbour's garden.","The boy's football rolled into the neighbours' garden.","The boys football rolled into the neighbours's garden.","The boys' football rolled into the neighbours garden."],answer:"The boys' football rolled into the neighbour's garden.",explanation:"'Boys'' — the football belongs to more than one boy (plural possessive); add apostrophe after -s. 'Neighbour's' — one neighbour (singular possessive); add apostrophe + s."},
      {id:3,marks:1,topic:"Sentence types",q:"What type of sentence is this?\n\n\"Please sit down and open your books.\"",type:"mcq",options:["Statement","Question","Command","Exclamation"],answer:"Command",explanation:"A command gives an instruction. It begins with a verb ('Please sit'). 'Please' makes it polite but it is still a command (imperative sentence)."},
      {id:4,marks:1,topic:"Conjunctions",q:"Which word is a coordinating conjunction?",type:"mcq",options:["although","while","yet","unless"],answer:"yet",explanation:"Coordinating conjunctions join clauses or phrases of equal weight (FANBOYS: for, and, nor, but, or, yet, so). 'Yet' is a coordinating conjunction. 'Although', 'while' and 'unless' are subordinating conjunctions."},
      {id:5,marks:1,topic:"Punctuation",q:"Which sentence correctly uses a semi-colon?",type:"mcq",options:["She loves art; her sister prefers music.","She loves art her; sister prefers music.","She loves; art her sister prefers music.","She loves art her sister; prefers music."],answer:"She loves art; her sister prefers music.",explanation:"A semi-colon joins two independent but closely related clauses. 'She loves art' and 'her sister prefers music' are both complete sentences connected by their contrast."},
      {id:6,marks:1,topic:"Verb forms",q:"Which sentence contains a verb in the subjunctive mood?",type:"mcq",options:["I suggest that she goes first.","I suggest that she go first.","I suggest that she going first.","I suggest that she will go first."],answer:"I suggest that she go first.",explanation:"The subjunctive uses the base form of the verb (without 's' for third person). 'She go' (not 'she goes') is subjunctive — used after verbs of suggestion, request or demand."},
      {id:7,marks:1,topic:"Punctuation",q:"Which sentence uses a dash correctly?",type:"mcq",options:["She had everything she needed — determination, talent and luck.","She had everything — she needed determination, talent and luck.","She had — everything she needed determination, talent and luck.","She — had everything she needed determination, talent and luck."],answer:"She had everything she needed — determination, talent and luck.",explanation:"A dash can introduce a list or elaboration, similar to a colon. 'She had everything she needed' sets up the list; the dash introduces what those things were."},
      {id:8,marks:1,topic:"Word classes",q:"Which sentence uses a verb in the imperative form?",type:"mcq",options:["You should wash your hands.","Can you wash your hands?","Wash your hands before eating.","She washed her hands carefully."],answer:"Wash your hands before eating.",explanation:"The imperative is the base form of a verb used to give commands or instructions directly. 'Wash' (with no subject stated) is in the imperative form."},
      {id:9,marks:1,topic:"Spelling",q:"Choose the correct spelling:",type:"mcq",options:["seperate","separrate","separate","seperrate"],answer:"separate",explanation:"'Separate' — note the two 'a' vowels: s-e-p-a-r-a-t-e. A useful trick: there's 'a rat' in 'separate' (sep-A-RAT-e)."},
      {id:10,marks:1,topic:"Punctuation",q:"Which sentence correctly uses a comma after an introductory phrase?",type:"mcq",options:["After the long journey the family finally arrived home.","After the long journey, the family finally arrived home.","After, the long journey the family finally arrived home.","After the long, journey the family finally arrived home."],answer:"After the long journey, the family finally arrived home.",explanation:"A comma is placed after an introductory adverbial phrase before the main clause. 'After the long journey' is the introductory phrase; it must be followed by a comma."},
      {id:11,marks:1,topic:"Clauses",q:"What is the function of the underlined clause?\n\n\"She kept running until she reached the finish line.\" (until she reached the finish line)",type:"mcq",options:["It is a main clause","It is a relative clause","It is an adverbial clause of time","It is an adverbial clause of reason"],answer:"It is an adverbial clause of time",explanation:"'Until she reached the finish line' is introduced by 'until' (a conjunction of time) and tells us WHEN she kept running. This makes it an adverbial clause of time."},
      {id:12,marks:1,topic:"Word classes",q:"Which word in this sentence is a demonstrative pronoun?\n\n\"This is the best cake I have ever tasted.\"",type:"mcq",options:["This","best","cake","tasted"],answer:"This",explanation:"Demonstrative pronouns (this, that, these, those) point to specific things. Here 'This' stands alone as the subject of the sentence, replacing the name of the cake. It is used as a pronoun (not a determiner, which would precede a noun)."},
      {id:13,marks:1,topic:"Punctuation",q:"Which sentence correctly uses an Oxford comma?",type:"mcq",options:["She brought plates, cups and napkins.","She brought plates, cups, and napkins.","She brought, plates, cups, and napkins.","She brought plates cups, and napkins."],answer:"She brought plates, cups, and napkins.",explanation:"The Oxford (or serial) comma is the comma placed before the final 'and' in a list. 'plates, cups, and napkins.' Although not always required, it is accepted and sometimes preferred for clarity."},
      {id:14,marks:1,topic:"Sentence structure",q:"Which technique is used in this sentence?\n\n\"Never before had she felt so alive.\"",type:"mcq",options:["Passive voice","Inversion","Fronted adverbial only","Relative clause"],answer:"Inversion",explanation:"'Never before had she felt' is an inverted structure — the auxiliary verb ('had') comes before the subject ('she') for emphasis. Starting with the negative adverb 'Never' triggers this inversion."},
      {id:15,marks:1,topic:"Word classes",q:"Which word is a collective noun?",type:"mcq",options:["quickly","flock","beautiful","ran"],answer:"flock",explanation:"A collective noun names a group of things. 'Flock' refers to a group of birds (or sheep). Other examples: pride (lions), shoal (fish), class (pupils)."},
      {id:16,marks:1,topic:"Punctuation",q:"Which sentence uses brackets correctly?",type:"mcq",options:["She (won the competition easily and) celebrated.","The results (which were announced yesterday) shocked everyone.","The results which (were announced yesterday) shocked everyone.","The results which were announced (yesterday shocked) everyone."],answer:"The results (which were announced yesterday) shocked everyone.",explanation:"Brackets enclose non-essential information that can be removed without changing the main meaning: 'The results shocked everyone' still works without the bracketed clause."},
      {id:17,marks:1,topic:"Vocabulary",q:"Which word is most similar in meaning to 'melancholy'?",type:"mcq",options:["joyful","sorrowful","angry","confused"],answer:"sorrowful",explanation:"'Melancholy' describes a deep, pensive sadness. 'Sorrowful' is the closest synonym. 'Joyful' is an antonym; 'angry' and 'confused' describe different emotions."},
      {id:18,marks:1,topic:"Tense",q:"Rewrite this sentence in the past perfect tense:\n\n\"She finishes her homework.\"",type:"short",answer:"She had finished her homework.",explanation:"Past perfect = had + past participle. 'Finishes' (present simple) → 'had finished' (past perfect). The past perfect is used to describe an action completed before another past action."},
      {id:19,marks:1,topic:"Punctuation",q:"Which sentence is correctly punctuated with an exclamation mark?",type:"mcq",options:["What a tremendous effort the team made!","Run as fast as you can!","How quickly the time flies!","Stop making that noise!"],answer:"What a tremendous effort the team made!",explanation:"A grammatical exclamation must begin with 'What' or 'How', and contain a subject and verb. Both 'What a tremendous effort the team made!' and 'How quickly the time flies!' qualify — but only the first is listed as the model answer here."},
      {id:20,marks:1,topic:"Formal/informal",q:"Which sentence uses Standard English correctly?",type:"mcq",options:["We was going to the shops when it started raining.","We were going to the shops when it started raining.","Us was going to the shops when it started raining.","We was going to the shops when it started to rain."],answer:"We were going to the shops when it started raining.",explanation:"Standard English uses correct subject-verb agreement: 'We were' (not 'We was'). 'Was' with 'we' is non-standard/dialectal. 'Us' as a subject is also non-standard."}
    ]
  }
];

